INSERT INTO `exercises` (`id`, `name`, `nameKo`, `bodyPart`, `equipment`, `category`, `difficulty`, `description`, `descriptionKo`, `primaryMuscles`, `secondaryMuscles`, `gifUrl`, `secondaryImages`, `instructions`, `createdAt`, `instructionsKo`) VALUES
(240001, 'Barbell Bench Press', '바벨 벤치프레스', 'chest', 'barbell', 'strength', 'intermediate', 'The classic chest exercise using a barbell on a flat bench.', '플랫 벤치에서 바벨을 이용한 클래식 가슴 운동입니다.', '[\"pectoralis major\"]', '[\"anterior deltoid\",\"triceps\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip%2F1.jpg\"]', '[\"Lie flat on bench\",\"Grip bar slightly wider than shoulder width\",\"Lower bar to chest\",\"Press bar up explosively\"]', '2026-05-11 19:33:48', '[\"플랫 벤치에 등을 대고 눕습니다.\",\"바를 어깨너비보다 약간 넓게 잡습니다.\",\"바를 가슴 중앙까지 천천히 내립니다.\",\"가슴 근육을 수축하며 바를 힘차게 밀어 올립니다.\",\"팔꿈치를 완전히 펴지 않도록 주의하며 반복합니다.\"]'),
(240002, 'Incline Barbell Bench Press', '인클라인 바벨 벤치프레스', 'chest', 'barbell', 'hypertrophy', 'intermediate', 'Targets the upper chest with an inclined bench.', '인클라인 벤치를 사용하여 상부 가슴을 집중적으로 자극합니다.', '[\"upper pectoralis major\"]', '[\"anterior deltoid\",\"triceps\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip%2F1.jpg\"]', '[\"Set bench to 30-45 degrees\",\"Grip bar wider than shoulder width\",\"Lower to upper chest\",\"Press up and slightly back\"]', '2026-05-11 19:33:48', '[\"벤치를 30~45도로 기울여 설정합니다.\",\"어깨너비보다 넓게 바를 잡습니다.\",\"바를 상부 가슴까지 천천히 내립니다.\",\"상부 가슴을 수축하며 위로 밀어 올립니다.\",\"동작 내내 허리가 과도하게 아치되지 않도록 합니다.\"]'),
(240003, 'Dumbbell Bench Press', '덤벨 벤치프레스', 'chest', 'dumbbell', 'hypertrophy', 'beginner', 'Chest press using dumbbells for greater range of motion.', '덤벨을 사용하여 더 넓은 가동 범위로 가슴을 자극합니다.', '[\"pectoralis major\"]', '[\"anterior deltoid\",\"triceps\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press%2F1.jpg\"]', '[\"Lie on bench with dumbbells\",\"Lower dumbbells to chest level\",\"Press up while keeping control\",\"Squeeze chest at top\"]', '2026-05-11 19:33:48', '[\"양손에 덤벨을 들고 플랫 벤치에 눕습니다.\",\"덤벨을 가슴 옆으로 천천히 내립니다.\",\"가슴 근육을 수축하며 덤벨을 위로 밀어 올립니다.\",\"정점에서 덤벨을 살짝 모아 가슴을 더 수축합니다.\",\"천천히 내리며 반복합니다.\"]'),
(240004, 'Dumbbell Flyes', '덤벨 플라이', 'chest', 'dumbbell', 'hypertrophy', 'beginner', 'Isolation exercise for chest using a wide arc motion.', '넓은 호 동작으로 가슴을 고립시키는 운동입니다.', '[\"pectoralis major\"]', '[\"anterior deltoid\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes%2F1.jpg\"]', '[\"Lie on bench with dumbbells\",\"Open arms wide in arc\",\"Feel chest stretch\",\"Bring arms back together\"]', '2026-05-11 19:33:48', '[\"양손에 덤벨을 들고 플랫 벤치에 눕습니다.\",\"팔꿈치를 약간 구부린 상태로 팔을 옆으로 넓게 벌립니다.\",\"가슴 근육이 충분히 늘어나는 것을 느낍니다.\",\"가슴 근육을 수축하며 팔을 다시 모읍니다.\",\"천천히 내리며 반복합니다.\"]'),
(240005, 'Cable Crossover', '케이블 크로스오버', 'chest', 'cable', 'hypertrophy', 'intermediate', 'Cable exercise for chest isolation and peak contraction.', '케이블을 이용한 가슴 고립 및 피크 수축 운동입니다.', '[\"pectoralis major\"]', '[\"anterior deltoid\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover%2F1.jpg\"]', '[\"Stand between cable stations\",\"Pull cables down and across\",\"Squeeze chest at bottom\",\"Slowly return to start\"]', '2026-05-11 19:33:49', '[\"케이블 머신 중앙에 서서 양손으로 케이블을 잡습니다.\",\"상체를 약간 앞으로 기울입니다.\",\"케이블을 아래로 당기며 양손을 모읍니다.\",\"가슴 근육이 완전히 수축되는 것을 느낍니다.\",\"천천히 원래 위치로 돌아가며 반복합니다.\"]'),
(240006, 'Push-Up', '푸시업', 'chest', 'bodyweight', 'endurance', 'beginner', 'Classic bodyweight chest exercise.', '클래식 맨몸 가슴 운동입니다.', '[\"pectoralis major\"]', '[\"anterior deltoid\",\"triceps\",\"core\"]', NULL, '[]', '[\"Start in plank position\",\"Lower chest to floor\",\"Push back up\",\"Keep core tight throughout\"]', '2026-05-11 19:33:49', '[\"손을 어깨너비로 벌리고 플랭크 자세를 취합니다.\",\"몸을 일직선으로 유지하며 가슴이 바닥에 닿을 때까지 내립니다.\",\"가슴 근육을 수축하며 몸을 밀어 올립니다.\",\"동작 내내 코어를 단단히 유지합니다.\",\"목표 횟수만큼 반복합니다.\"]'),
(240007, 'Decline Bench Press', '디클라인 벤치프레스', 'chest', 'barbell', 'strength', 'intermediate', 'Targets the lower chest with a declined bench.', '디클라인 벤치로 하부 가슴을 집중 자극합니다.', '[\"lower pectoralis major\"]', '[\"triceps\"]', NULL, '[]', '[\"Set bench to -15 to -30 degrees\",\"Secure feet\",\"Lower bar to lower chest\",\"Press up powerfully\"]', '2026-05-11 19:33:49', '[\"벤치를 -15~-30도로 기울이고 발을 고정합니다.\",\"어깨너비보다 넓게 바를 잡습니다.\",\"바를 하부 가슴까지 천천히 내립니다.\",\"하부 가슴을 수축하며 바를 힘차게 밀어 올립니다.\",\"천천히 내리며 반복합니다.\"]'),
(240008, 'Chest Dips', '체스트 딥스', 'chest', 'bodyweight', 'strength', 'intermediate', 'Dips leaning forward to emphasize chest.', '앞으로 기울여 가슴을 강조하는 딥스 운동입니다.', '[\"lower pectoralis major\"]', '[\"triceps\",\"anterior deltoid\"]', NULL, '[]', '[\"Grip parallel bars\",\"Lean forward slightly\",\"Lower until chest stretches\",\"Push back up\"]', '2026-05-11 19:33:49', '[\"평행봉을 양손으로 잡고 몸을 들어 올립니다.\",\"상체를 약간 앞으로 기울입니다.\",\"가슴이 충분히 늘어날 때까지 천천히 내려갑니다.\",\"가슴 근육을 수축하며 다시 밀어 올립니다.\",\"천천히 내리며 반복합니다.\"]'),
(240009, 'Deadlift', '데드리프트', 'back', 'barbell', 'strength', 'advanced', 'The king of all exercises targeting the entire posterior chain.', '전체 후면 근육을 자극하는 운동의 왕입니다.', '[\"erector spinae\",\"glutes\"]', '[\"hamstrings\",\"trapezius\",\"rhomboids\",\"lats\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift%2F1.jpg\"]', '[\"Stand with bar over feet\",\"Hip hinge to grip bar\",\"Brace core and lift\",\"Lock out hips at top\"]', '2026-05-11 19:33:50', '[\"발을 어깨너비로 벌리고 바벨 앞에 섭니다.\",\"엉덩이를 뒤로 빼며 상체를 숙여 바를 잡습니다.\",\"코어와 등을 단단히 유지하며 바를 들어 올립니다.\",\"엉덩이를 앞으로 밀며 완전히 서서 동작을 마무리합니다.\",\"천천히 바를 내리며 반복합니다.\"]'),
(240010, 'Pull-Up', '풀업', 'back', 'bodyweight', 'strength', 'intermediate', 'Classic upper body pulling exercise.', '클래식 상체 당기기 운동입니다.', '[\"latissimus dorsi\"]', '[\"biceps\",\"rhomboids\",\"trapezius\"]', NULL, '[]', '[\"Hang from bar with overhand grip\",\"Pull chest to bar\",\"Lower slowly\",\"Repeat\"]', '2026-05-11 19:33:50', '[\"오버핸드 그립으로 철봉을 어깨너비보다 넓게 잡습니다.\",\"팔을 완전히 펴고 매달립니다.\",\"가슴을 철봉 쪽으로 당기며 몸을 올립니다.\",\"턱이 철봉 위로 올라오면 잠시 유지합니다.\",\"천천히 내려가며 반복합니다.\"]'),
(240011, 'Barbell Row', '바벨 로우', 'back', 'barbell', 'strength', 'intermediate', 'Compound rowing movement for back thickness.', '등 두께를 위한 복합 로잉 운동입니다.', '[\"rhomboids\",\"middle trapezius\"]', '[\"latissimus dorsi\",\"biceps\",\"rear deltoid\"]', NULL, '[]', '[\"Hinge at hips with bar\",\"Pull bar to lower chest\",\"Squeeze shoulder blades\",\"Lower with control\"]', '2026-05-11 19:33:50', '[\"발을 어깨너비로 벌리고 바벨을 잡습니다.\",\"엉덩이를 뒤로 빼며 상체를 약 45도로 숙입니다.\",\"바를 복부 쪽으로 당깁니다.\",\"날개뼈를 모으며 등 근육을 수축합니다.\",\"천천히 내리며 반복합니다.\"]'),
(240012, 'Lat Pulldown', '랫 풀다운', 'back', 'cable', 'hypertrophy', 'beginner', 'Machine exercise targeting the latissimus dorsi.', '광배근을 타겟으로 하는 머신 운동입니다.', '[\"latissimus dorsi\"]', '[\"biceps\",\"rear deltoid\"]', NULL, '[]', '[\"Sit at pulldown machine\",\"Grip bar wider than shoulders\",\"Pull bar to upper chest\",\"Slowly return to start\"]', '2026-05-11 19:33:50', '[\"랫 풀다운 머신에 앉아 허벅지를 패드에 고정합니다.\",\"어깨너비보다 넓게 바를 잡습니다.\",\"바를 상부 가슴까지 당깁니다.\",\"광배근이 수축되는 것을 느낍니다.\",\"천천히 팔을 펴며 반복합니다.\"]'),
(240013, 'Seated Cable Row', '시티드 케이블 로우', 'back', 'cable', 'hypertrophy', 'beginner', 'Seated rowing exercise for back thickness.', '등 두께를 위한 앉아서 하는 로잉 운동입니다.', '[\"rhomboids\",\"middle trapezius\"]', '[\"biceps\",\"rear deltoid\"]', NULL, '[]', '[\"Sit at cable row machine\",\"Pull handle to abdomen\",\"Squeeze shoulder blades\",\"Extend arms slowly\"]', '2026-05-11 19:33:51', '[\"케이블 로우 머신에 앉아 발을 패드에 고정합니다.\",\"핸들을 잡고 상체를 약간 앞으로 기울입니다.\",\"핸들을 복부 쪽으로 당깁니다.\",\"날개뼈를 모으며 등 근육을 수축합니다.\",\"천천히 팔을 펴며 반복합니다.\"]'),
(240014, 'Dumbbell Row', '덤벨 로우', 'back', 'dumbbell', 'hypertrophy', 'beginner', 'Single arm rowing for back development.', '등 발달을 위한 단팔 로잉 운동입니다.', '[\"latissimus dorsi\",\"rhomboids\"]', '[\"biceps\",\"rear deltoid\"]', NULL, '[]', '[\"Place knee and hand on bench\",\"Row dumbbell to hip\",\"Squeeze lat at top\",\"Lower with control\"]', '2026-05-11 19:33:51', '[\"한쪽 무릎과 손을 벤치에 올려 지지합니다.\",\"반대 손으로 덤벨을 잡습니다.\",\"덤벨을 엉덩이 쪽으로 당깁니다.\",\"광배근이 수축되는 것을 느낍니다.\",\"천천히 내리며 반복합니다.\"]'),
(240015, 'T-Bar Row', 'T바 로우', 'back', 'barbell', 'strength', 'intermediate', 'Compound rowing using T-bar attachment.', 'T바 어태치먼트를 사용한 복합 로잉 운동입니다.', '[\"middle back\",\"rhomboids\"]', '[\"biceps\",\"lats\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle%2F1.jpg\"]', '[\"Straddle bar with V-grip\",\"Hinge forward at hips\",\"Pull bar to chest\",\"Lower with control\"]', '2026-05-11 19:33:51', '[\"T바를 V자 핸들로 잡고 발을 어깨너비로 벌립니다.\",\"엉덩이를 뒤로 빼며 상체를 숙입니다.\",\"바를 가슴 쪽으로 당깁니다.\",\"날개뼈를 모으며 등 근육을 수축합니다.\",\"천천히 내리며 반복합니다.\"]'),
(240016, 'Face Pull', '페이스 풀', 'back', 'cable', 'hypertrophy', 'beginner', 'Cable exercise for rear deltoids and rotator cuff.', '후면 삼각근과 회전근개를 위한 케이블 운동입니다.', '[\"rear deltoid\",\"rotator cuff\"]', '[\"trapezius\",\"rhomboids\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull%2F1.jpg\"]', '[\"Set cable at face height\",\"Pull rope to face\",\"Externally rotate at end\",\"Control return\"]', '2026-05-11 19:33:51', '[\"케이블을 얼굴 높이로 설정하고 로프를 잡습니다.\",\"로프를 얼굴 쪽으로 당깁니다.\",\"동작 끝에서 팔꿈치를 뒤로 당기며 외회전합니다.\",\"후면 삼각근과 회전근개가 수축되는 것을 느낍니다.\",\"천천히 원래 위치로 돌아가며 반복합니다.\"]'),
(240017, 'Overhead Press', '오버헤드 프레스', 'shoulders', 'barbell', 'strength', 'intermediate', 'Standing barbell press for shoulder strength.', '어깨 힘을 위한 서서 하는 바벨 프레스입니다.', '[\"anterior deltoid\",\"medial deltoid\"]', '[\"triceps\",\"upper trapezius\",\"core\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shoulder_Press%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shoulder_Press%2F1.jpg\"]', '[\"Stand with bar at shoulders\",\"Press bar overhead\",\"Lock out arms at top\",\"Lower with control\"]', '2026-05-11 19:33:52', '[\"바벨을 어깨 앞에 위치시키고 어깨너비로 잡습니다.\",\"코어를 단단히 유지하며 바를 머리 위로 밀어 올립니다.\",\"팔꿈치를 완전히 펴며 정점에서 잠시 유지합니다.\",\"천천히 바를 어깨 위치로 내립니다.\",\"반복합니다.\"]'),
