(240095, 'Butterfly Stretch', '나비 스트레칭', 'stretching', 'none', 'flexibility', 'beginner', 'Inner thigh and groin stretch.', '내전근과 사타구니 스트레칭입니다.', '[\"inner thighs\",\"groin\"]', '[\"hip flexors\"]', NULL, '[]', '[\"Sit with soles of feet together\",\"Hold feet with hands\",\"Press knees toward floor\",\"Hold 60 seconds\"]', '2026-05-11 19:34:10', '[\"바닥에 앉아 발바닥을 서로 붙입니다.\",\"양손으로 발을 잡습니다.\",\"무릎을 바닥 쪽으로 누릅니다.\",\"내전근이 늘어나는 것을 느낍니다.\",\"60초간 유지합니다.\"]'),
(240096, 'Downward Dog', '다운워드 독', 'stretching', 'none', 'flexibility', 'beginner', 'Yoga pose stretching hamstrings and calves.', '햄스트링과 종아리를 스트레칭하는 요가 자세입니다.', '[\"hamstrings\",\"calves\"]', '[\"shoulders\",\"back\"]', NULL, '[]', '[\"Start on hands and knees\",\"Push hips up and back\",\"Straighten legs\",\"Press heels toward floor\"]', '2026-05-11 19:34:11', '[\"네발 기기 자세에서 시작합니다.\",\"엉덩이를 위로 들어 올립니다.\",\"다리를 최대한 펍니다.\",\"발뒤꿈치를 바닥 쪽으로 누릅니다.\",\"햄스트링과 종아리가 늘어나는 것을 느낍니다.\"]'),
(240097, 'World\'s Greatest Stretch', '세계 최고의 스트레칭', 'stretching', 'none', 'flexibility', 'intermediate', 'Multi-joint mobility exercise.', '다관절 가동성 운동입니다.', '[\"hip flexors\",\"thoracic spine\",\"hamstrings\"]', '[\"shoulders\",\"groin\"]', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cat_Stretch%2F0.jpg', '[\"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cat_Stretch%2F1.jpg\"]', '[\"Start in lunge position\",\"Place hand inside front foot\",\"Rotate upper body up\",\"Reach arm to ceiling\"]', '2026-05-11 19:34:11', '[\"런지 자세를 취합니다.\",\"앞발 안쪽에 손을 놓습니다.\",\"상체를 회전하며 팔을 천장 쪽으로 뻗습니다.\",\"전신의 여러 근육이 늘어나는 것을 느낍니다.\",\"반대쪽으로 반복합니다.\"]'),
(240098, 'Battle Ropes', '배틀 로프', 'full_body', 'none', 'cardio', 'intermediate', 'High intensity conditioning with battle ropes.', '배틀 로프를 이용한 고강도 컨디셔닝 운동입니다.', '[\"shoulders\",\"arms\",\"core\"]', '[\"legs\",\"back\"]', NULL, '[]', '[\"Hold rope ends\",\"Create waves alternately\",\"Keep core tight\",\"Maintain for set time\"]', '2026-05-11 19:34:11', '[\"로프 끝을 양손에 잡습니다.\",\"무릎을 약간 구부리고 코어를 단단히 유지합니다.\",\"번갈아가며 파도를 만들듯 로프를 움직입니다.\",\"일정한 리듬을 유지합니다.\",\"목표 시간만큼 반복합니다.\"]'),
(240099, 'Farmer\'s Walk', '파머스 워크', 'full_body', 'dumbbell', 'strength', 'beginner', 'Loaded carry for grip and core strength.', '그립력과 코어 힘을 위한 무게 들고 걷기 운동입니다.', '[\"forearms\",\"core\",\"trapezius\"]', '[\"legs\",\"shoulders\"]', NULL, '[]', '[\"Hold heavy dumbbells at sides\",\"Walk with upright posture\",\"Keep core braced\",\"Set down with control\"]', '2026-05-11 19:34:11', '[\"무거운 덤벨을 양손에 듭니다.\",\"상체를 수직으로 유지하며 걷습니다.\",\"코어를 단단히 유지합니다.\",\"목표 거리 또는 시간만큼 걷습니다.\",\"덤벨을 조심스럽게 내려놓습니다.\"]'),
(240100, 'Sled Push', '슬레드 푸시', 'full_body', 'machine', 'cardio', 'intermediate', 'Pushing weighted sled for conditioning.', '컨디셔닝을 위한 무게 슬레드 밀기 운동입니다.', '[\"quadriceps\",\"glutes\"]', '[\"shoulders\",\"core\"]', NULL, '[]', '[\"Grip sled handles\",\"Lean forward and drive legs\",\"Push sled across floor\",\"Maintain low position\"]', '2026-05-11 19:34:12', '[\"슬레드 핸들을 잡습니다.\",\"상체를 앞으로 기울이며 다리로 밀어냅니다.\",\"낮은 자세를 유지합니다.\",\"목표 거리만큼 슬레드를 밉니다.\",\"코어를 단단히 유지합니다.\"]');

INSERT INTO `exercises` (`id`, `name`, `nameKo`, `bodyPart`, `equipment`, `category`, `difficulty`, `description`, `descriptionKo`, `primaryMuscles`, `secondaryMuscles`, `gifUrl`, `secondaryImages`, `instructions`, `createdAt`, `instructionsKo`) VALUES
(240101, 'Cable Kickback', '케이블 킥백', 'glutes', 'cable', 'hypertrophy', 'beginner', 'Cable exercise for glute isolation.', '둔근 고립을 위한 케이블 운동입니다.', '[\"glutes\"]', '[\"hamstrings\"]', NULL, '[]', '[\"Attach ankle strap to cable\",\"Face cable machine\",\"Kick leg back and up\",\"Squeeze glute at top\"]', '2026-05-11 19:34:12', '[\"발목에 케이블 스트랩을 연결합니다.\",\"케이블 머신을 마주 보고 섭니다.\",\"다리를 뒤로 들어 올립니다.\",\"둔근이 수축되는 것을 느낍니다.\",\"천천히 내리며 반복합니다.\"]'),
(240102, 'Donkey Kick', '당나귀 킥', 'glutes', 'bodyweight', 'hypertrophy', 'beginner', 'Bodyweight glute exercise on all fours.', '네발 기기 자세로 하는 맨몸 둔근 운동입니다.', '[\"glutes\"]', '[\"hamstrings\",\"core\"]', NULL, '[]', '[\"Start on hands and knees\",\"Kick one leg up and back\",\"Squeeze glute at top\",\"Lower and repeat\"]', '2026-05-11 19:34:12', '[\"네발 기기 자세를 취합니다.\",\"한 다리를 뒤로 들어 올립니다.\",\"둔근이 수축되는 것을 느낍니다.\",\"천천히 내리며 반복합니다.\",\"반대 다리로 반복합니다.\"]'),
(240103, 'Abductor Machine', '어브덕터 머신', 'glutes', 'machine', 'hypertrophy', 'beginner', 'Machine exercise for hip abductors.', '고관절 외전근을 위한 머신 운동입니다.', '[\"hip abductors\",\"glute medius\"]', '[]', NULL, '[]', '[\"Sit in abductor machine\",\"Push legs outward\",\"Hold briefly\",\"Return slowly\"]', '2026-05-11 19:34:12', '[\"어브덕터 머신에 앉아 패드를 허벅지 바깥쪽에 위치시킵니다.\",\"다리를 바깥쪽으로 밀어 냅니다.\",\"고관절 외전근이 수축되는 것을 느낍니다.\",\"천천히 원래 위치로 돌아옵니다.\",\"반복합니다.\"]');

DROP TABLE IF EXISTS `routine_exercises`;
CREATE TABLE `routine_exercises` (
  `id` int NOT NULL AUTO_INCREMENT,
  `routineId` int NOT NULL,
  `exerciseId` int NOT NULL,
  `order` int NOT NULL,
  `sets` int DEFAULT '3',
  `reps` int DEFAULT '10',
  `restSeconds` int DEFAULT '90',
  `notes` text DEFAULT NULL,
  `weightKg` float DEFAULT NULL,
  `setDetails` json DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=150001;

DROP TABLE IF EXISTS `routines`;
CREATE TABLE `routines` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `name` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `goal` enum('hypertrophy','fat_loss','strength','endurance','flexibility','general') NOT NULL,
  `daysPerWeek` int DEFAULT '3',
  `isPublic` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=150001;

INSERT INTO `routines` (`id`, `userId`, `name`, `description`, `goal`, `daysPerWeek`, `isPublic`, `createdAt`, `updatedAt`) VALUES
