DROP TABLE IF EXISTS `user_goals`;
CREATE TABLE `user_goals` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `goal` enum('hypertrophy','fat_loss','strength','endurance','flexibility','general') NOT NULL,
  `targetWeight` float DEFAULT NULL,
  `weeklyWorkouts` int DEFAULT '3',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `heightCm` float DEFAULT NULL,
  `gender` enum('male','female') DEFAULT NULL,
  `birthYear` int DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=210001;

INSERT INTO `user_goals` (`id`, `userId`, `goal`, `targetWeight`, `weeklyWorkouts`, `isActive`, `createdAt`, `updatedAt`, `heightCm`, `gender`, `birthYear`) VALUES
