DROP TABLE IF EXISTS `workout_logs`;
CREATE TABLE `workout_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sessionId` int NOT NULL,
  `exerciseId` int NOT NULL,
  `setNumber` int NOT NULL,
  `reps` int DEFAULT NULL,
  `weightKg` float DEFAULT NULL,
  `durationSeconds` int DEFAULT NULL,
  `distanceM` float DEFAULT NULL,
  `isWarmup` tinyint(1) NOT NULL DEFAULT '0',
  `notes` text DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `rpe` tinyint DEFAULT NULL,
  `memo` text DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=30001;

DROP TABLE IF EXISTS `workout_sessions`;
CREATE TABLE `workout_sessions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `routineId` int DEFAULT NULL,
  `name` varchar(200) DEFAULT NULL,
  `startedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completedAt` timestamp NULL DEFAULT NULL,
  `durationMinutes` int DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `totalVolume` float DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `workoutDate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=210001;

